"""Run from the folder containing pyproject.toml:  python fix_report.py
Fixes two crashes in `abuselens report` / the dashboard: a non-numeric week-over-week column, and
the per-host takedown table when no host has enough URLs yet."""
from pathlib import Path

root = Path.cwd()
if not (root / "pyproject.toml").exists():
    raise SystemExit("Run this from the folder that contains pyproject.toml")
FILES = [
    ('src/abuselens/reporting/brief.py', '"""Weekly auto-generated risk brief (markdown), written for product/policy stakeholders."""\nfrom __future__ import annotations\n\nimport datetime as dt\nfrom pathlib import Path\n\nimport pandas as pd\n\nfrom .. import config\nfrom ..analytics import survival\n\n\ndef _md(df: pd.DataFrame, n: int = 10) -> str:\n    return df.head(n).to_markdown(index=False) if len(df) else "_no data_"\n\n\ndef add_wow(vol: pd.DataFrame, prior: pd.DataFrame) -> pd.DataFrame:\n    """Attach the previous week\'s count and the week-over-week change (NaN when no prior week)."""\n    out = vol.merge(prior, on="abuse_type", how="left")\n    out["urls_7d"] = out["urls_7d"].astype(float)\n    out["urls_prev_7d"] = out["urls_prev_7d"].astype(float).fillna(0.0)\n    base = out["urls_prev_7d"].where(out["urls_prev_7d"] > 0)\n    out["wow_change"] = ((out["urls_7d"] - out["urls_prev_7d"]) / base).round(2)\n    return out\n\n\ndef build(con, model_meta: dict | None = None, monitor: dict | None = None) -> str:\n    today = dt.date.today()\n    vol = con.execute("""\n        SELECT abuse_type, count(*) AS urls_7d FROM stg_malicious_urls\n        WHERE event_ts >= (SELECT max(event_ts) FROM stg_malicious_urls) - INTERVAL 7 DAY\n        GROUP BY 1 ORDER BY 2 DESC""").df()\n    prior = con.execute("""\n        SELECT abuse_type, count(*) AS urls_prev_7d FROM stg_malicious_urls\n        WHERE event_ts < (SELECT max(event_ts) FROM stg_malicious_urls) - INTERVAL 7 DAY\n          AND event_ts >= (SELECT max(event_ts) FROM stg_malicious_urls) - INTERVAL 14 DAY\n        GROUP BY 1""").df()\n    vol = add_wow(vol, prior)\n\n    brands = con.execute("""SELECT brand, n_urls FROM brand_targets\n        WHERE month = (SELECT max(month) FROM brand_targets) ORDER BY n_urls DESC""").df()\n    tlds = con.execute("SELECT tld, sum(n_urls) AS n_urls FROM tld_abuse GROUP BY 1 ORDER BY 2 DESC").df()\n    camps = con.execute("""SELECT host, path_shape, n_urls, active_days, first_seen\n        FROM campaigns ORDER BY n_urls DESC""").df()\n\n    lines = [f"# AbuseLens weekly risk brief — {today:%d %b %Y}", "",\n             "## Headline", ""]\n    if len(vol):\n        top = vol.iloc[0]\n        lines.append(f"- **{top.abuse_type}** is the largest abuse category: {int(top.urls_7d):,} new URLs "\n                     f"in the last 7 days.")\n    if len(brands):\n        lines.append(f"- Most impersonated brand this month: **{brands.iloc[0].brand}** "\n                     f"({int(brands.iloc[0].n_urls)} phishing URLs).")\n    if len(camps):\n        lines.append(f"- Largest active campaign: {int(camps.iloc[0].n_urls)} URLs on "\n                     f"`{camps.iloc[0].host}` sharing one URL template.")\n    try:\n        td = survival.load(con)\n        if len(td) > 30:\n            km = survival.kaplan_meier(td)\n            lines.append(f"- Median malware-URL lifetime: **{km.iloc[0].median_hours:.0f} hours**; "\n                         f"{km.iloc[0].survival_7d:.0%} are still live after 7 days.")\n    except Exception:\n        td = None\n    lines += ["", "## Volume by abuse type (7d vs previous 7d)", "", _md(vol),\n              "", "## Most impersonated brands (current month)", "", _md(brands),\n              "", "## Most abused TLDs", "", _md(tlds),\n              "", "## Largest campaigns", "", _md(camps, 8)]\n\n    if td is not None and len(td) > 30:\n        lines += ["", "## Takedown speed (Kaplan–Meier)", "",\n                  "Hosts ranked by slowest median time-to-takedown (≥30 URLs each; censored URLs "\n                  "handled correctly):", "",\n                  _md(survival.kaplan_meier(td, "host").round(3), 8)]\n\n    if model_meta:\n        m = model_meta["metrics"]\n        lines += ["", "## Detection model", "",\n                  f"- Decision: {model_meta.get(\'decision\')}",\n                  f"- Trained on {model_meta[\'train_range\'][0][:10]} → {model_meta[\'train_range\'][1][:10]}; "\n                  f"tested on later data {model_meta[\'test_range\'][0][:10]} → {model_meta[\'test_range\'][1][:10]}",\n                  f"- PR-AUC {m[\'pr_auc\']:.3f}, ROC-AUC {m[\'roc_auc\']:.3f}",\n                  f"- At the frozen threshold: recall {m[\'recall\']:.1%}, FPR {m[\'fpr\']:.2%}",\n                  f"- Precision at assumed {model_meta[\'assumed_prevalence\']:.0%} real-world prevalence: "\n                  f"{m.get(\'precision_at_prevalence\', float(\'nan\')):.1%}"]\n    if monitor:\n        lines += ["", "## Monitoring", ""]\n        lines += [f"- ⚠️ {a}" for a in monitor["alerts"]] or ["- No drift or decay alerts."]\n        if len(monitor["decay"]):\n            lines += ["", _md(monitor["decay"].round(3), 12)]\n    lines += ["", "---", "_Data: abuse.ch URLhaus, OpenPhish, PhishTank, Tranco, Common Crawl. "\n              "Auto-generated by AbuseLens._"]\n    return "\\n".join(lines)\n\n\ndef write(text: str, out_dir: Path | None = None) -> Path:\n    out_dir = Path(out_dir or config.REPORT_DIR)\n    out_dir.mkdir(parents=True, exist_ok=True)\n    p = out_dir / f"risk_brief_{dt.date.today():%Y-%m-%d}.md"\n    p.write_text(text, encoding="utf-8")\n    return p\n'),
    ('src/abuselens/analytics/survival.py', '"""Takedown survival analysis on URLhaus lifetimes (right-censored: still-online URLs)."""\nfrom __future__ import annotations\n\nimport pandas as pd\nfrom lifelines import CoxPHFitter, KaplanMeierFitter\nfrom lifelines.statistics import multivariate_logrank_test\n\n\ndef load(con) -> pd.DataFrame:\n    df = con.execute("SELECT * FROM stg_takedown WHERE lifetime_hours IS NOT NULL").df()\n    df["lifetime_hours"] = df["lifetime_hours"].clip(lower=0.01)\n    return df\n\n\nKM_COLUMNS = ["group", "n", "n_taken_down", "median_hours", "survival_24h", "survival_7d",\n              "ci_lower_7d", "ci_upper_7d"]\n\n\ndef kaplan_meier(df: pd.DataFrame, group_col: str | None = None, min_n: int = 30) -> pd.DataFrame:\n    """Median time-to-takedown (hours) overall or per group, with 95% CI."""\n    groups = [("all", df)] if group_col is None else [\n        (g, d) for g, d in df.groupby(group_col) if len(d) >= min_n]\n    rows = []\n    for name, d in groups:\n        km = KaplanMeierFitter().fit(d["lifetime_hours"], d["taken_down"])\n        ci = km.confidence_interval_survival_function_\n        rows.append({"group": name, "n": len(d), "n_taken_down": int(d["taken_down"].sum()),\n                     "median_hours": float(km.median_survival_time_),\n                     "survival_24h": float(km.predict(24)), "survival_7d": float(km.predict(168)),\n                     "ci_lower_7d": float(ci.iloc[:, 0].asof(168)) if len(ci) else None,\n                     "ci_upper_7d": float(ci.iloc[:, 1].asof(168)) if len(ci) else None})\n    if not rows:  # e.g. no host has >= min_n URLs yet\n        return pd.DataFrame(columns=KM_COLUMNS)\n    return pd.DataFrame(rows).sort_values("median_hours", ascending=False).reset_index(drop=True)\n\n\ndef logrank_p(df: pd.DataFrame, group_col: str, min_n: int = 30) -> float:\n    d = df.groupby(group_col).filter(lambda x: len(x) >= min_n)\n    if d[group_col].nunique() < 2:\n        return float("nan")\n    return float(multivariate_logrank_test(d["lifetime_hours"], d[group_col], d["taken_down"]).p_value)\n\n\ndef cox_by_host(df: pd.DataFrame, top_n: int = 10, min_n: int = 30) -> pd.DataFrame:\n    """Cox PH hazard ratios for the most-abused hosts vs. everyone else.\n\n    HR < 1 => URLs on that host are taken down *more slowly* than the baseline.\n    """\n    counts = df["host"].value_counts()\n    top = [h for h in counts.index if counts[h] >= min_n][:top_n]\n    if not top:\n        return pd.DataFrame(columns=["host", "hazard_ratio", "ci_lower", "ci_upper", "p"])\n    X = pd.DataFrame({f"h_{i}": (df["host"] == h).astype(int) for i, h in enumerate(top)})\n    X["lifetime_hours"], X["taken_down"] = df["lifetime_hours"], df["taken_down"]\n    cph = CoxPHFitter(penalizer=0.01).fit(X, "lifetime_hours", "taken_down")\n    s = cph.summary\n    return pd.DataFrame({\n        "host": top, "hazard_ratio": s["exp(coef)"].values,\n        "ci_lower": s["exp(coef) lower 95%"].values, "ci_upper": s["exp(coef) upper 95%"].values,\n        "p": s["p"].values}).sort_values("hazard_ratio").reset_index(drop=True)\n'),
]
for rel, text in FILES:
    (root / rel).write_text(text, encoding="utf-8", newline="")
    print("patched", rel)
